const { useRef, useState } = React;

const KIT_STYLE = `
  @scope {
    .cb-grid {
      background-image: radial-gradient(var(--tau-line-1) 1px, transparent 1px);
      background-size: 16px 16px;
    }
    .cb-range { accent-color: var(--tau-accent); }
  }
`;

// 实验台骨架：左侧舞台放被演示元素，右侧面板放参数，底部是实时生成的声明
const Lab = ({ stage, children, code }) => (
  <div className="@container flex flex-col gap-3">
    <style>{KIT_STYLE}</style>
    <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
      <div className="cb-grid relative flex min-w-0 items-center justify-center rounded-tau-md border border-line-1 p-4">
        {stage}
      </div>
      <div className="flex min-w-0 flex-col gap-3 rounded-tau-md border border-line-1 p-3">{children}</div>
    </div>
    {code}
  </div>
);

const Options = ({ label, options, value, onChange }) => (
  <div className="flex min-w-0 flex-col gap-1.5">
    <span className="text-tau-sm text-ink-3">{label}</span>
    <div className="flex flex-wrap gap-1.5">
      {options.map(option => {
        const item = typeof option === "string" ? { value: option, label: option } : option;
        const active = item.value === value;
        return (
          <button
            key={item.value}
            type="button"
            aria-pressed={active}
            onClick={() => onChange(item.value)}
            className={`max-w-full cursor-pointer rounded-tau-sm border px-2 py-0.5 text-left font-tau-mono text-tau-sm transition-colors ${
              active ? "border-accent bg-accent-soft text-accent-text" : "border-line-1 bg-surface text-ink-2 hover:bg-hover"
            }`}
          >
            {item.label}
          </button>
        );
      })}
    </div>
  </div>
);

const Slider = ({ label, value, min, max, step = 1, onChange, format = value => value }) => (
  <label className="flex min-w-0 flex-col gap-1">
    <span className="flex items-baseline justify-between gap-2 text-tau-sm text-ink-3">
      <span>{label}</span>
      <span className="font-tau-mono text-ink-1">{format(value)}</span>
    </span>
    <input
      type="range"
      min={min}
      max={max}
      step={step}
      value={value}
      onChange={event => onChange(Number(event.target.value))}
      className="cb-range h-1.5 w-full cursor-pointer"
    />
  </label>
);

const Readout = ({ rows }) => (
  <dl className="m-0 grid grid-cols-[auto_minmax(0,1fr)] gap-x-3 gap-y-1 border-t border-line-2 pt-2.5 text-tau-sm">
    {rows.map(([label, value]) => (
      <React.Fragment key={label}>
        <dt className="text-ink-3">{label}</dt>
        <dd className="m-0 min-w-0 break-all text-right font-tau-mono text-ink-1">{value}</dd>
      </React.Fragment>
    ))}
  </dl>
);

// 声明读数：每行由字符串和 { mark } 段组成，mark 段是当前正在调的参数
const Code = ({ lines }) => (
  <code className="block min-w-0 break-all rounded-tau-md bg-hover px-3 py-2 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
    {lines.map((line, lineIndex) => (
      <div key={lineIndex}>
        {line.map((part, index) =>
          typeof part === "string" ? (
            <span key={index}>{part}</span>
          ) : (
            <span key={index} className="rounded-tau-sm bg-accent-soft px-0.5 text-accent-text">
              {part.mark}
            </span>
          )
        )}
      </div>
    ))}
  </code>
);

const clamp = (value, min, max) => Math.min(max, Math.max(min, value));
// 在元素上按下并拖动：回调盒内坐标（CSS 像素）与盒子尺寸
const dragProps = (ref, onMove) => {
  const move = event => {
    const rect = ref.current?.getBoundingClientRect();
    if (!rect?.width || !rect.height) return;
    onMove(clamp(event.clientX - rect.left, 0, rect.width), clamp(event.clientY - rect.top, 0, rect.height), rect);
  };
  return {
    onPointerDown: event => {
      event.currentTarget.setPointerCapture?.(event.pointerId);
      move(event);
    },
    onPointerMove: event => {
      if (event.buttons & 1) move(event);
    },
  };
};

// 辅助线：底下垫一层 surface 色描边，在任何渐变色上都清晰
const Guide = ({ dashed = true, ...props }) => (
  <>
    <line {...props} className="stroke-surface" strokeWidth="3" strokeLinecap="round" />
    <line {...props} className="stroke-ink-1" strokeWidth="1.25" strokeDasharray={dashed ? "4 3" : undefined} />
  </>
);
const Dot = ({ x, y }) => <circle cx={x} cy={y} r="4.5" className="fill-surface stroke-ink-1" strokeWidth="1.5" />;
const Overlay = ({ width, height, children }) =>
  width > 0 && height > 0 ? (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      className="pointer-events-none absolute inset-0 size-full overflow-hidden rounded-tau-sm"
    >
      {children}
    </svg>
  ) : null;

const HUE_COUNT = 15;
const HUES = Array.from({ length: HUE_COUNT }, (_, index) => `hsl(${(index * 360) / HUE_COUNT}, 80%, 50%)`).join(", ");
const trim = (value, digits) => String(Number(value.toFixed(digits)));
// 角度 → 圆周上的点：0deg 朝上、顺时针，与 conic-gradient 一致
const polar = (cx, cy, r, degree) => {
  const radian = (degree * Math.PI) / 180;
  return { x: cx + r * Math.sin(radian), y: cy - r * Math.cos(radian) };
};
const arcPath = (cx, cy, r, from, delta) => {
  const start = polar(cx, cy, r, from);
  const end = polar(cx, cy, r, from + delta);
  return `M ${start.x} ${start.y} A ${r} ${r} 0 ${Math.abs(delta) > 180 ? 1 : 0} ${delta > 0 ? 1 : 0} ${end.x} ${end.y}`;
};

const UNITS = ["deg", "turn", "rad", "grad"];
const DISC = 200;
const formatAngle = (degree, unit) =>
  ({
    deg: `${degree}deg`,
    turn: `${trim(degree / 360, 4)}turn`,
    rad: `${trim((degree * Math.PI) / 180, 4)}rad`,
    grad: `${trim(degree / 0.9, 2)}grad`,
  })[unit];

const Component = () => {
  const discRef = useRef(null);
  const [angle, setAngle] = useState(45);
  const [unit, setUnit] = useState("deg");
  const from = formatAngle(angle, unit);
  const tip = polar(DISC / 2, DISC / 2, DISC / 2 - 6, angle);
  const drag = dragProps(discRef, (x, y) => {
    const degree = Math.round((Math.atan2(x - DISC / 2, DISC / 2 - y) * 180) / Math.PI);
    setAngle((degree + 360) % 360);
  });

  return (
    <Lab
      stage={
        <div
          ref={discRef}
          {...drag}
          className="relative size-[200px] shrink-0 cursor-pointer touch-none rounded-full shadow-card"
          style={{ backgroundImage: `conic-gradient(from ${from}, ${HUES})` }}
        >
          <Overlay width={DISC} height={DISC}>
            <Guide x1={DISC / 2} y1={DISC / 2} x2={DISC / 2} y2={6} />
            {angle > 0 && <path d={arcPath(DISC / 2, DISC / 2, 28, 0, angle)} fill="none" className="stroke-ink-1" strokeWidth="1.5" />}
            <Guide x1={DISC / 2} y1={DISC / 2} x2={tip.x} y2={tip.y} dashed={false} />
            <Dot x={tip.x} y={tip.y} />
            <Dot x={DISC / 2} y={DISC / 2} />
          </Overlay>
        </div>
      }
      code={<Code lines={[["background-image: conic-gradient(from ", { mark: from }, ", hsl(0, 80%, 50%), …);"]]} />}
    >
      <span className="text-tau-meta text-ink-3">在圆盘上拖动设置起始角，虚线是 0deg（正上方）。</span>
      <Slider label="起始角" value={angle} min={0} max={359} onChange={setAngle} format={value => `${value}°`} />
      <Options label="单位" options={UNITS} value={unit} onChange={setUnit} />
      <Readout
        rows={[
          ...UNITS.map(item => [item, formatAngle(angle, item)]),
          ...(angle === 0 ? [["<zero>", "也可直接写 from 0"]] : []),
        ]}
      />
    </Lab>
  );
};

const { useEffect, useRef, useState } = React;

const KIT_STYLE = `
  @scope {
    .cb-grid {
      background-image: radial-gradient(var(--tau-line-1) 1px, transparent 1px);
      background-size: 16px 16px;
    }
    .cb-range { accent-color: var(--tau-accent); }
  }
`;

// 实验台骨架：左侧舞台放被演示元素，右侧面板放参数，底部是实时生成的声明
const Lab = ({ stage, children, code }) => (
  <div className="@container flex flex-col gap-3">
    <style>{KIT_STYLE}</style>
    <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
      <div className="cb-grid relative flex min-w-0 items-center justify-center rounded-tau-md border border-line-1 p-4">
        {stage}
      </div>
      <div className="flex min-w-0 flex-col gap-3 rounded-tau-md border border-line-1 p-3">{children}</div>
    </div>
    {code}
  </div>
);

