            type="button"
            aria-pressed={active}
            onClick={() => onChange(item.value)}
            className={`max-w-full cursor-pointer rounded-tau-sm border px-2 py-0.5 text-left font-tau-mono text-tau-sm transition-colors ${
              active ? "border-accent bg-accent-soft text-accent-text" : "border-line-1 bg-surface text-ink-2 hover:bg-hover"
            }`}
          >
            {item.label}
          </button>
        );
      })}
    </div>
  </div>
);

// 声明读数：每行由字符串和 { mark } 段组成，mark 段是当前正在调的参数
const Code = ({ lines }) => (
  <code className="block min-w-0 break-all rounded-tau-md bg-hover px-3 py-2 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
    {lines.map((line, lineIndex) => (
      <div key={lineIndex}>
        {line.map((part, index) =>
          typeof part === "string" ? (
            <span key={index}>{part}</span>
          ) : (
            <span key={index} className="rounded-tau-sm bg-accent-soft px-0.5 text-accent-text">
              {part.mark}
            </span>
          )
        )}
      </div>
    ))}
  </code>
);

// 浏览器能检测时以实测为准，否则回退到语法解析结论
const supports = value => {
  if (typeof CSS === "undefined" || typeof CSS.supports !== "function") return null;
  return CSS.supports("background-image", value);
};

const SPACES = [{ value: "", label: "省略" }, "srgb", "srgb-linear", "oklab", "lab", "xyz", "display-p3"];
const PAIRS = [
  { value: "red, blue", label: "red → blue" },
  { value: "yellow, blue", label: "yellow → blue" },
  { value: "black, white", label: "black → white" },
];
const gradientOf = (space, pair) => `conic-gradient(${space ? `in ${space}, ` : ""}${pair})`;
const supported = value => (typeof CSS === "undefined" || typeof CSS.supports !== "function" ? true : CSS.supports("background-image", value));

const Disc = ({ space, pair }) => {
  const gradient = gradientOf(space, pair);
  const ok = supported(gradient);
  return (
    <div className="flex flex-col items-center gap-2">
      <div
        className={`grid size-[140px] place-items-center rounded-full ${ok ? "shadow-card" : "border border-dashed border-line-1"}`}
        style={ok ? { backgroundImage: gradient } : undefined}
      >
        {!ok && <span className="text-tau-meta text-ink-3">当前环境不支持</span>}
      </div>
      <code className="rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">{space ? `in ${space}` : "省略 in"}</code>
    </div>
  );
};

const Component = () => {
  const [left, setLeft] = useState("srgb");
  const [right, setRight] = useState("oklab");
  const [pair, setPair] = useState("red, blue");

  return (
    <Lab
      stage={
        <div className="flex flex-wrap justify-center gap-6">
          <Disc space={left} pair={pair} />
          <Disc space={right} pair={pair} />
        </div>
      }
      code={
        <Code
          lines={[left, right].map(space => [
            "background-image: conic-gradient(",
            ...(space ? [{ mark: `in ${space}` }, ", "] : []),
            `${pair});`,
          ])}
        />
      }
    >
      <Options label="颜色" options={PAIRS} value={pair} onChange={setPair} />
      <Options label="左侧 <rectangular-color-space>" options={SPACES} value={left} onChange={setLeft} />
      <Options label="右侧 <rectangular-color-space>" options={SPACES} value={right} onChange={setRight} />
      <span className="text-tau-meta text-ink-3">省略 in 时默认 oklab；但颜色全是 hex、关键字、rgb()、hsl() 这类旧写法时，按 srgb 插值。</span>
    </Lab>
  );
};

const { useState } = React;

const KIT_STYLE = `
  @scope {
    .cb-grid {
      background-image: radial-gradient(var(--tau-line-1) 1px, transparent 1px);
      background-size: 16px 16px;
    }
