const SPACES = ["hsl", "hwb", "lch", "oklch"];
const METHODS = [{ value: "", label: "省略" }, "shorter hue", "longer hue", "increasing hue", "decreasing hue"];
const colorOf = (space, hue) =>
  ({
    hsl: `hsl(${hue} 80% 50%)`,
    hwb: `hwb(${hue} 10% 10%)`,
    lch: `lch(65% 75 ${hue})`,
    oklch: `oklch(0.7 0.17 ${hue})`,
  })[space];
const RING = 140;
