// CSS Color 4 的色相修正：返回实际走过的角度差
const hueDelta = (method, from, to) => {
  let a = from;
  let b = to;
  const diff = b - a;
  if (method === "longer hue") {
    if (diff > 0 && diff < 180) a += 360;
    else if (diff > -180 && diff <= 0) b += 360;
  } else if (method === "increasing hue") {
    if (b < a) b += 360;
  } else if (method === "decreasing hue") {
    if (a < b) a += 360;
  } else if (diff > 180) a += 360;
  else if (diff < -180) b += 360;
  return b - a;
};

const Component = () => {
