  const delta = hueDelta(method || "shorter hue", fromHue, toHue);
  const interpolation = `in ${space}${method ? ` ${method}` : ""}`;
  const colors = `${colorOf(space, fromHue)}, ${colorOf(space, toHue)}`;
  const ring = [0, 90, 180, 270, 360].map(hue => colorOf(space, hue)).join(", ");
  const center = RING / 2;
  const radius = RING / 2 - 10;
  const half = delta / 2;
  const start = polar(center, center, radius, fromHue);
  const end = polar(center, center, radius, fromHue + delta);

  return (
