              />
              <Overlay width={RING} height={RING}>
                {delta !== 0 && (
                  <>
                    {[0, half].map(offset => (
                      <React.Fragment key={offset}>
                        <path d={arcPath(center, center, radius, fromHue + offset, half)} fill="none" className="stroke-surface" strokeWidth="6" strokeLinecap="round" />
                        <path d={arcPath(center, center, radius, fromHue + offset, half)} fill="none" className="stroke-ink-1" strokeWidth="2.5" strokeLinecap="round" />
                      </React.Fragment>
                    ))}
                  </>
                )}
                <Dot x={start.x} y={start.y} />
                <circle cx={end.x} cy={end.y} r="4.5" className="fill-ink-1 stroke-surface" strokeWidth="1.5" />
                <Label x={center} y={center}>{`${delta > 0 ? "+" : ""}${delta}°`}</Label>
              </Overlay>
            </div>
            <span className="text-tau-sm text-ink-3">色相环上的插值路径</span>
          </div>
        </div>
      }
      code={<Code lines={[["background-image: conic-gradient(", { mark: interpolation }, `, ${colors});`]]} />}
    >
      <Options label="<polar-color-space>" options={SPACES} value={space} onChange={setSpace} />
      <Options label="<hue-interpolation-method>" options={METHODS} value={method} onChange={setMethod} />
      <Slider label="起点色相" value={fromHue} min={0} max={359} onChange={setFromHue} format={value => `${value}°`} />
      <Slider label="终点色相" value={toHue} min={0} max={359} onChange={setToHue} format={value => `${value}°`} />
      <Readout
        rows={[
          ["生效方法", method || "shorter hue"],
          ["色相变化", `${delta > 0 ? "+" : ""}${delta}°`],
          ["路径", `${fromHue}° → ${fromHue + delta}°`],
        ]}
      />
    </Lab>
  );
};

