const trim = (value, digits) => String(Number(value.toFixed(digits)));
// 角度 → 圆周上的点：0deg 朝上、顺时针，与 conic-gradient 一致
const polar = (cx, cy, r, degree) => {
  const radian = (degree * Math.PI) / 180;
  return { x: cx + r * Math.sin(radian), y: cy - r * Math.cos(radian) };
};
const SETS = [
  { value: "two", label: "双色", colors: ["red", "blue"] },
  { value: "three", label: "三色", colors: ["#f06a0e", "#4f7cff", "#2bb673"] },
  { value: "rainbow", label: "彩虹", colors: ["red", "orange", "yellow", "green", "blue", "purple"] },
];
const BLENDS = [{ value: "smooth", label: "渐变" }, { value: "hard", label: "硬边" }];
const CLOSURES = [{ value: "closed", label: "闭合" }, { value: "open", label: "不闭合" }];
const UNITS = ["%", "deg"];
const DISC = 200;

const Component = () => {
  const [set, setSet] = useState("two");
  const [blend, setBlend] = useState("smooth");
  const [closure, setClosure] = useState("closed");
  const [unit, setUnit] = useState("%");
  const colors = SETS.find(item => item.value === set).colors;
  const full = unit === "%" ? 100 : 360;
  const format = value => `${trim(value, 1)}${unit}`;
  // 渐变：只写颜色，位置均分；硬边：每个颜色写起止两个位置，相邻色标重合
  const smooth = closure === "closed" ? [...colors, colors[0]] : colors;
  const stops =
    blend === "smooth"
      ? smooth.map((color, index) => ({ color, at: [(index / (smooth.length - 1)) * 100] }))
      : colors.map((color, index) => ({ color, at: [(index / colors.length) * 100, ((index + 1) / colors.length) * 100] }));
  const list = stops
    .map(({ color, at }) => (blend === "smooth" ? color : `${color} ${at.map(value => format((value / 100) * full)).join(" ")}`))
    .join(", ");
  const ticks = [...new Set(stops.flatMap(item => item.at))].filter(value => value < 100);
  const seam = blend === "hard" ? "每段之间都是硬边" : closure === "closed" ? "首尾同色，没有接缝" : "首尾不同色，0deg 处有一条硬接缝";

  return (
