        </div>
      }
      code={<Code lines={[["background-image: conic-gradient(", { mark: list }, ");"]]} />}
    >
      <Options label="颜色" options={SETS} value={set} onChange={setSet} />
      <Options label="过渡" options={BLENDS} value={blend} onChange={setBlend} />
      {blend === "smooth" ? (
        <Options label="首尾" options={CLOSURES} value={closure} onChange={setClosure} />
      ) : (
        <Options label="位置单位" options={UNITS} value={unit} onChange={setUnit} />
      )}
      <Readout
        rows={[
          ["色标数", `${stops.reduce((sum, item) => sum + item.at.length, 0)}`],
          ["接缝", seam],
        ]}
      />
      <span className="text-tau-meta text-ink-3">圆盘边缘的刻度是色标所在的角度。</span>
    </Lab>
  );
};

